const body = $input.first().json.body || $input.first().json;
const table = body.table || '';
const r = body.record || {};
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const row = (k, v) => (v == null || v === '' || (Array.isArray(v) && !v.length)) ? '' : `<tr><td style="padding:6px 12px 6px 0;color:#77806e;white-space:nowrap;vertical-align:top">${k}</td><td style="padding:6px 0">${esc(Array.isArray(v) ? v.join(', ') : v)}</td></tr>`;
const types = {kids:"Kids' party", birthday:'Birthday or celebration', bbq:'BBQ or cook-out', dinner:'Formal dinner', wedding:'Wedding celebration', tournament:'Tournament or festival', community:'Community event', corporate:'Corporate', other:'Something else'};
const spaces = {clubhouse:'Bar & clubhouse', balcony:'Balcony', braai:'Outdoor kitchen & braai', marquee:'Marquee', pitches:'Pitches', unsure:'Not sure'};
let subject, rows;
if (table === 'enquiries') {
  subject = `New enquiry: ${r.name} · ${types[r.event_type] || r.event_type || 'event'}${r.preferred_date ? ' · ' + r.preferred_date : ''}`;
  rows = [
    row('Name', r.name), row('Email', r.email), row('Phone', r.phone), row('Event', types[r.event_type] || r.event_type),
    row('Preferred date', r.preferred_date ? r.preferred_date + (r.dates_flexible ? ' (flexible)' : '') : (r.dates_flexible ? 'Flexible' : null)),
    row('Times', (r.start_time || r.finish_time) ? `${r.start_time || '?'} → ${r.finish_time || '?'}` : null),
    row('Guests', (r.adults != null || r.children != null) ? `${r.adults ?? 0} adults, ${r.children ?? 0} children` : null),
    row('Spaces', (r.spaces || []).map(s => spaces[s] || s)), row('Own caterer', r.caterer), row('Club member', r.member), row('Message', r.message)
  ].join('');
} else if (table === 'signups') {
  subject = `New community sign-up: ${r.name}`;
  rows = [row('Name', r.name), row('Email', r.email), row('Mobile', r.mobile), row('Wants', [r.news ? 'Email news' : null, r.whatsapp ? 'WhatsApp group invite' : null].filter(Boolean))].join('');
} else {
  subject = `Website event: ${table || 'unknown'}`;
  rows = row('Payload', JSON.stringify(body));
}
const html = `<div style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;font-size:15px;color:#2C3327;line-height:1.5"><p style="margin:0 0 12px"><strong>${esc(subject)}</strong></p><table style="border-collapse:collapse">${rows}</table><p style="margin:18px 0 0;color:#77806e;font-size:13px">Open the staff area to update the status: <a href="https://kingsclubhouse.co.uk/staff/">kingsclubhouse.co.uk/staff</a></p></div>`;
return [{ json: { subject, html, table, replyTo: r.email || '' } }];
